#!/usr/bin/env bash
set -euo pipefail

mode="${1:-}"
shift || true
case "$mode" in
shellcheck | shfmt) ;;
*)
	echo "usage: lint-staged-shell.sh {shellcheck|shfmt} FILE..." >&2
	exit 2
	;;
esac

files=()
for file in "$@"; do
	[ -f "$file" ] || continue
	if head -n 1 "$file" | grep -Eq '^#!.*(sh|bash|zsh)([[:space:]]|$)'; then
		files+=("$file")
	fi
done

((${#files[@]} > 0)) || exit 0
# bin/repo is GENERATED by purpose-repo-commands and carries a
# "Do not edit" header. Its formatting belongs to the generator: the
# committed output is not shfmt-formatted (1055 lines of diff) and
# reformatting it here would be undone by the next regeneration. It also
# prints a literal `eval "$(direnv export bash)"` recovery instruction, so
# the SC2016 rule fires on an intended literal. Every hand-written file
# keeps full strictness; the two exemptions are scoped to the generated
# dispatcher.
generated=()
handwritten=()
for file in "${files[@]}"; do
	case "$file" in
	bin/repo | */bin/repo) generated+=("$file") ;;
	*) handwritten+=("$file") ;;
	esac
done
if [ "$mode" = shellcheck ]; then
	rc=0
	if ((${#handwritten[@]} > 0)); then
		shellcheck --external-sources "${handwritten[@]}" || rc=$?
	fi
	if ((${#generated[@]} > 0)); then
		shellcheck --external-sources --exclude=SC2016 "${generated[@]}" || rc=$?
	fi
	exit "$rc"
fi
if ((${#handwritten[@]} > 0)); then
	exec shfmt -d "${handwritten[@]}"
fi
exit 0
